  /** Hash table to hold semaphore for each configured name service. */
  private Map<String, Semaphore> permits;

  /** Hash table to hold rejected permits for each configured name service. */
  private Map<String, LongAdder> rejectedPermits;

  public void init(Configuration conf) {
    this.permits = new HashMap<>();
    this.rejectedPermits = new HashMap<>();
  }

  @Override
  public boolean acquirePermit(String nsId) {
    try {
      LOG.debug("Taking lock for nameservice {}", nsId);
      boolean success = this.permits.get(nsId).tryAcquire(1, TimeUnit.SECONDS);
      if (!success) {
        incrRejectedPermits(nsId);
      }
      return success;
    } catch (InterruptedException e) {
      LOG.debug("Cannot get a permit for nameservice {}", nsId);
    }
    incrRejectedPermits(nsId);
    return false;
  }

  protected void incrRejectedPermits(String nsId) {
    this.rejectedPermits.computeIfAbsent(nsId, k -> new LongAdder()).increment();
  }

  @Override
  public String getRejectedPermitsPerNsJSON() {
    Map<String, Long> rejectedPermitsMap = new HashMap<>();
    rejectedPermits.forEach((k, v) -> rejectedPermitsMap.put(k, v.longValue()));
    return JSON.toString(rejectedPermitsMap);
  }
