73	  public static JSONArray getJmx(String beanQuery, String webAddress,
74	      URLConnectionFactory connectionFactory, String scheme) {
75	    JSONArray ret = null;
76	    BufferedReader reader = null;
77	    try {
78	      String host = webAddress;
79	      int port = -1;
