94	      reader = new BufferedReader(isr);
95	
96	      StringBuilder sb = new StringBuilder();
97	      String line = null;
98	      while ((line = reader.readLine()) != null) {
99	        sb.append(line);
100	      }
101	      String jmxOutput = sb.toString();
102	
103	      // Parse JSON
