43	/**
44	 * Test the Router handlers fairness control rejects
45	 * requests when the handlers are overloaded.
46	 */
47	public class TestRouterHandlersFairness {
48	
49	  private static final Logger LOG =
50	      LoggerFactory.getLogger(TestRouterHandlersFairness.class);
51	
52	  private StateStoreDFSCluster cluster;
53	
54	  @After
55	  public void cleanup() {
56	    if (cluster != null) {
57	      cluster.shutdown();
58	      cluster = null;
59	    }
60	  }
61	
62	  private void setupCluster(boolean fairnessEnable, boolean ha)
63	      throws Exception {
64	    // Build and start a federated cluster
65	    cluster = new StateStoreDFSCluster(ha, 2);
66	    Configuration routerConf = new RouterConfigBuilder()
67	        .stateStore()
68	        .rpc()
69	        .build();
70	
71	    // Fairness control
72	    if (fairnessEnable) {
73	      routerConf.setClass(
74	          RBFConfigKeys.DFS_ROUTER_FAIRNESS_POLICY_CONTROLLER_CLASS,
75	          StaticRouterRpcFairnessPolicyController.class,
76	          RouterRpcFairnessPolicyController.class);
77	    }
78	
79	    // With two name services configured, each nameservice has 1 permit and
80	    // fan-out calls have 1 permit.
81	    routerConf.setInt(RBFConfigKeys.DFS_ROUTER_HANDLER_COUNT_KEY, 3);
82	
83	    // Datanodes not needed for this test.
84	    cluster.setNumDatanodesPerNameservice(0);
85	
86	    cluster.addRouterOverrides(routerConf);
87	    cluster.startCluster();
88	    cluster.startRouters();
89	    cluster.waitClusterUp();
90	  }
91	
92	  @Test
93	  public void testFairnessControlOff() throws Exception {
94	    setupCluster(false, false);
95	    startLoadTest(false);
96	  }
97	
98	  @Test
99	  public void testFairnessControlOn() throws Exception {
100	    setupCluster(true, false);
101	    startLoadTest(true);
102	  }
103	
104	  /**
105	   * Start a generic load test as a client against a cluster which has either
106	   * fairness configured or not configured. Test will spawn a set of 100
107	   * threads to simulate concurrent request to test routers. If fairness is
108	   * enabled, the test will successfully report the failure of some threads
109	   * to continue with StandbyException. If fairness is not configured, all
110	   * threads of the same test should successfully complete all the rpcs.
111	   *
112	   * @param fairness Flag to indicate if fairness management is on/off.
113	   * @throws Exception Throws exception.
114	   */
115	  private void startLoadTest(boolean fairness)
116	      throws Exception {
117	
118	    // Concurrent requests
119	    startLoadTest(true, fairness);
120	
121	    // Sequential requests
122	    startLoadTest(false, fairness);
123	  }
124	
125	  private void startLoadTest(final boolean isConcurrent, final boolean fairness)
126	      throws Exception {
127	
128	    RouterContext routerContext = cluster.getRandomRouter();
129	    if (fairness) {
130	      if (isConcurrent) {
131	        LOG.info("Taking fanout lock first");
132	        // take the lock for concurrent NS to block fanout calls
133	        assertTrue(routerContext.getRouter().getRpcServer()
134	            .getRPCClient().getRouterRpcFairnessPolicyController()
135	            .acquirePermit(RouterRpcFairnessConstants.CONCURRENT_NS));
136	      } else {
137	        for (String ns : cluster.getNameservices()) {
138	          LOG.info("Taking lock first for ns: {}", ns);
139	          assertTrue(routerContext.getRouter().getRpcServer()
140	              .getRPCClient().getRouterRpcFairnessPolicyController()
141	              .acquirePermit(ns));
142	        }
143	      }
144	    }
145	    URI address = routerContext.getFileSystemURI();
146	    Configuration conf = new HdfsConfiguration();
147	    final int numOps = 10;
148	    final AtomicInteger overloadException = new AtomicInteger();
149	
150	    for (int i = 0; i < numOps; i++) {
151	      DFSClient routerClient = null;
152	      try {
153	        routerClient = new DFSClient(address, conf);
154	        String clientName = routerClient.getClientName();
155	        ClientProtocol routerProto = routerClient.getNamenode();
156	        if (isConcurrent) {
157	          invokeConcurrent(routerProto, clientName);
158	        } else {
159	          invokeSequential(routerProto);
160	        }
161	      } catch (RemoteException re) {
162	        IOException ioe = re.unwrapRemoteException();
163	        assertTrue("Wrong exception: " + ioe,
164	            ioe instanceof StandbyException);
165	        assertExceptionContains("is overloaded for NS", ioe);
166	        overloadException.incrementAndGet();
167	      } catch (Throwable e) {
168	        throw e;
169	      } finally {
170	        if (routerClient != null) {
171	          try {
172	            routerClient.close();
173	          } catch (IOException e) {
174	            LOG.error("Cannot close the client");
175	          }
176	        }
177	      }
178	      overloadException.get();
179	    }
180	
181	    if (fairness) {
182	      assertTrue(overloadException.get() > 0);
183	      if (isConcurrent) {
184	        LOG.info("Release fanout lock that was taken before test");
185	        // take the lock for concurrent NS to block fanout calls
186	        routerContext.getRouter().getRpcServer()
187	            .getRPCClient().getRouterRpcFairnessPolicyController()
188	            .releasePermit(RouterRpcFairnessConstants.CONCURRENT_NS);
189	      } else {
190	        for (String ns : cluster.getNameservices()) {
191	          routerContext.getRouter().getRpcServer()
192	              .getRPCClient().getRouterRpcFairnessPolicyController()
193	              .releasePermit(ns);
194	        }
195	      }
196	    } else {
197	      assertEquals("Number of failed RPCs without fairness configured",
198	          0, overloadException.get());
199	    }
200	  }
201	
202	  private void invokeSequential(ClientProtocol routerProto) throws IOException {
203	    routerProto.getFileInfo("/test.txt");
204	  }
205	
206	  private void invokeConcurrent(ClientProtocol routerProto, String clientName)
207	      throws IOException {
208	    routerProto.renewLease(clientName);
209	  }
